#!/usr/bin/env python3
import os,sys,json,re,sqlite3,secrets,hashlib,base64,threading,time,datetime,urllib.parse,socket,struct,uuid
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
DB='/app/data.db'; NODE=int(os.environ.get('NODE_ID','0')); PORT=int(os.environ.get('PORT',8000))
LOCK=threading.RLock(); clients=[]; irc_clients=[]

def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def db():
 c=sqlite3.connect(DB,check_same_thread=False); c.row_factory=sqlite3.Row; c.execute('PRAGMA journal_mode=WAL'); return c
def init():
 with LOCK:
  c=db()
  c.executescript('''CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT,avatar_url TEXT,status_text TEXT,status_emoji TEXT);
  CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER); CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT);
  CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
  CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER,is_dm INTEGER DEFAULT 0,topic TEXT,is_archived INTEGER DEFAULT 0);
  CREATE TABLE IF NOT EXISTS channel_members(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
  CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0,event_id INTEGER);
  CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
  CREATE TABLE IF NOT EXISTS pins(message_id INTEGER PRIMARY KEY,pinned_by INTEGER,pinned_at TEXT);
  CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,uploader_id INTEGER,filename TEXT,content_type TEXT,size INTEGER,data BLOB,created_at TEXT);
  CREATE TABLE IF NOT EXISTS invites(code TEXT PRIMARY KEY,workspace_id INTEGER,invited_user_id INTEGER,expires INTEGER,max_uses INTEGER,uses INTEGER DEFAULT 0);
  CREATE TABLE IF NOT EXISTS groups_(id INTEGER PRIMARY KEY,workspace_id INTEGER,handle TEXT,name TEXT,creator_id INTEGER,user_ids TEXT);
  CREATE TABLE IF NOT EXISTS seq(channel_id INTEGER PRIMARY KEY,n INTEGER DEFAULT 0)''')
  c.commit(); c.close()
init()
def q(sql,args=(),one=False):
 with LOCK:
  c=db(); r=c.execute(sql,args); rows=r.fetchall() if not one else r.fetchone(); c.commit(); c.close(); return rows
def user(r):
 return {k:r[k] for k in ('id','username','display_name','timezone','avatar_url','status_text','status_emoji')}
def channel(r): return {'id':r['id'],'workspace_id':r['workspace_id'],'name':r['name'],'is_private':bool(r['is_private']),'is_dm':bool(r['is_dm']),'topic':r['topic'] or '','is_archived':bool(r['is_archived'])}
def msg(r):
 a=q('select * from users where id=?',(r['author_id'],),True); rs=q('select emoji,user_id from reactions where message_id=?',(r['id'],))
 em={}
 for x in rs: em.setdefault(x['emoji'],[]).append(x['user_id'])
 return {'id':r['id'],'channel_id':r['channel_id'],'author_id':r['author_id'],'author':user(a),'body':r['body'],'parent_id':r['parent_id'],'reply_count':q('select count(*) n from messages where parent_id=? and deleted=0',(r['id'],),True)['n'],'created_at':r['created_at'],'edited_at':r['edited_at'],'files':[],'reactions':[{'emoji':k,'count':len(v),'user_ids':v} for k,v in em.items()],'mentions':[],'event_id':r['event_id']}
def broadcast(o,chan=None):
 data=json.dumps(o).encode()
 for c in list(clients):
  try:
   if chan is None or chan in c[1]: ws_send(c[0],data)
  except: pass
 for s,nick,joined in list(irc_clients):
  if chan in joined and o.get('type')=='message.created':
   try:
    ch=q('select * from channels where id=?',(chan,),True); w=q('select * from workspaces where id=?',(ch['workspace_id'],),True)
    s.sendall(irc_line(':'+nick+'!user@host PRIVMSG #'+w['slug']+'/'+ch['name']+' :'+o['message']['body']))
   except: pass
def ws_send(s,b):
 s.sendall(bytes([0x81,len(b)])+b if len(b)<126 else bytes([0x81,126])+struct.pack('!H',len(b))+b)
def irc_line(x): return (x+'\r\n').encode()
class H(BaseHTTPRequestHandler):
 protocol_version='HTTP/1.1'
 def log_message(self,*a): pass
 def sendj(self,code,o,headers={}):
  b=json.dumps(o).encode(); self.send_response(code); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(b)))
  for k,v in headers.items(): self.send_header(k,v)
  self.end_headers(); self.wfile.write(b)
 def body(self):
  n=int(self.headers.get('Content-Length',0)); return json.loads(self.rfile.read(n) or b'{}')
 def auth(self):
  t=self.headers.get('Authorization','').replace('Bearer ',''); r=q('select u.* from tokens t join users u on u.id=t.user_id where t.token=?',(t,),True)
  return r
 def req(self,code,o): self.sendj(code,o)
 def do_GET(self):
  if self.path=='/' or self.path.startswith('/?'): return self.html()
  if self.path=='/api/health': return self.sendj(200,{'status':'ok','node_id':NODE})
  if self.path.startswith('/api/ws'): return self.websocket()
  u=self.auth()
  if self.path.startswith('/api/auth/me'): return self.sendj(200,{'user':user(u)}) if u else self.sendj(401,{'error':'unauthorized'})
  if not u: return self.sendj(401,{'error':'unauthorized'})
  p=urllib.parse.urlparse(self.path); x=p.path.split('/')
  if x[2]=='users':
   r=u if x[3]=='me' else q('select * from users where id=?',(x[3],),True); return self.sendj(200,{'user':user(r)}) if r else self.sendj(404,{'error':'not found'})
  if x[2]=='workspaces':
   if len(x)==3: return self.sendj(200,{'workspaces':[dict(r) for r in q('select * from workspaces where id in (select workspace_id from members where user_id=?)',(u['id'],))]})
   w=q('select * from workspaces where slug=?',(x[3],),True)
   if not w:return self.sendj(404,{})
   if len(x)>4 and x[4]=='members': return self.sendj(200,{'members':[dict(r) for r in q('select user_id,role from members where workspace_id=?',(w['id'],))]})
   if len(x)>4 and x[4]=='groups': return self.sendj(200,{'groups':[{'id':r['id'],'handle':r['handle'],'name':r['name'],'member_user_ids':json.loads(r['user_ids'])} for r in q('select * from groups_ where workspace_id=?',(w['id'],))]})
   cs=[channel(r) for r in q('select * from channels where workspace_id=? and (is_archived=0 or ?)',(w['id'],'include_archived' in p.query))]
   return self.sendj(200,{'workspace':dict(w),'channels':cs,'read_state':[]})
  if x[2]=='channels':
   c=q('select * from channels where id=?',(x[3],),True) if len(x)>3 else None
   if not c:return self.sendj(404,{})
   if len(x)>4 and x[4]=='members': return self.sendj(200,{'members':[user(q('select * from users where id=?',(r['user_id'],),True)) for r in q('select user_id from channel_members where channel_id=?',(c['id'],))]})
   if len(x)>4 and x[4]=='messages':
    rows=q('select * from messages where channel_id=? and deleted=0 and parent_id is null order by id desc',(c['id'],)); return self.sendj(200,{'messages':[msg(r) for r in rows],'next_cursor':None})
   if len(x)>4 and x[4]=='pins': return self.sendj(200,{'pins':[],'next_cursor':None})
   return self.sendj(200,{'channel':channel(c)})
  if x[2]=='messages':
   m=q('select * from messages where id=?',(x[3],),True) if len(x)>3 else None
   if not m:return self.sendj(404,{})
   if len(x)>4 and x[4]=='replies': return self.sendj(200,{'replies':[msg(r) for r in q('select * from messages where parent_id=? and deleted=0 order by id',(m['id'],))],'next_cursor':None})
   return self.sendj(200,{'message':msg(m)})
  if x[2]=='files':
   f=q('select * from files where id=?',(x[3],),True)
   if not f:return self.sendj(404,{})
   if len(x)>4:return self.send_response(200) or self.end_headers()
   return self.sendj(200,{'file':{k:f[k] for k in ('id','uploader_id','filename','content_type','size','created_at')}})
  return self.sendj(404,{})
 def do_POST(self):
  if self.path=='/api/auth/register':
   b=self.body(); 
   if not re.fullmatch(r'[A-Za-z0-9_]+',b.get('username','')) or len(b.get('password',''))<8:return self.sendj(400,{})
   try: uid=q('insert into users(username,password,display_name,timezone,avatar_url,status_text,status_emoji) values(?,?,?,?,?,?,?)',(b['username'],b['password'],b.get('display_name',b['username']),'UTC','','',''),); 
   except sqlite3.IntegrityError:return self.sendj(409,{})
   r=q('select * from users where username=?',(b['username'],),True); t=secrets.token_urlsafe(24); q('insert into tokens values(?,?)',(t,r['id'])); return self.sendj(201,{'user':user(r),'token':t})
  if self.path=='/api/auth/login':
   b=self.body(); r=q('select * from users where username=? and password=?',(b.get('username'),b.get('password')),True)
   if not r:return self.sendj(401,{})
   t=secrets.token_urlsafe(24); q('insert into tokens values(?,?)',(t,r['id'],)); return self.sendj(200,{'user':user(r),'token':t})
  u=self.auth()
  if not u:return self.sendj(401,{})
  p=self.path.split('/'); b=self.body()
  if p[2]=='workspaces':
   if len(p)==3:
    try:q('insert into workspaces(slug,name,owner_id,join_mode) values(?,?,?,?)',(b['slug'],b['name'],u['id'],'open'))
    except sqlite3.IntegrityError:return self.sendj(409,{})
    w=q('select * from workspaces where slug=?',(b['slug'],),True); q('insert into members values(?,?,?)',(w['id'],u['id'],'owner')); q('insert into channels(workspace_id,name,is_private,topic) values(?,?,0,"")',(w['id'],'general')); c=q('select * from channels where workspace_id=?',(w['id'],),True); q('insert into channel_members values(?,?)',(c['id'],u['id'])); return self.sendj(201,{'workspace':dict(w),'general_channel':channel(c)})
   if len(p)>4 and p[4]=='channels':
    w=q('select * from workspaces where slug=?',(p[3],),True)
    if not w:return self.sendj(404,{})
    if q('select 1 from channels where workspace_id=? and name=?',(w['id'],b.get('name')),True):return self.sendj(409,{})
    q('insert into channels(workspace_id,name,is_private,topic) values(?,?,?,?)',(w['id'],b['name'],int(b.get('is_private',False)),b.get('topic',''))); c=q('select * from channels where workspace_id=? and name=?',(w['id'],b['name']),True); q('insert into channel_members values(?,?)',(c['id'],u['id'])); return self.sendj(201,{'channel':channel(c)})
  if p[2]=='channels':
   c=q('select * from channels where id=?',(p[3],),True)
   if not c:return self.sendj(404,{})
   if len(p)>4 and p[4]=='join': q('insert or ignore into channel_members values(?,?)',(c['id'],u['id'])); q('insert or ignore into members values(?,?,?)',(c['workspace_id'],u['id'],'member')); return self.sendj(200,{'channel':channel(c)})
   if len(p)>4 and p[4]=='messages':
    if not b.get('body'):return self.sendj(400,{})
    n=q('select coalesce(n,0)+1 n from seq where channel_id=?',(c['id'],),True); q('insert or replace into seq values(?,?)',(c['id'],n['n'])); q('insert into messages(channel_id,author_id,body,parent_id,created_at,event_id) values(?,?,?,?,?,?)',(c['id'],u['id'],b['body'],b.get('parent_id'),now(),n['n'])); m=q('select * from messages where rowid=last_insert_rowid()',(),True); o=msg(m); broadcast({'type':'message.reply' if m['parent_id'] else 'message.created','event_id':n['n'],'channel_id':c['id'],'message':o},c['id']); return self.sendj(201,{'message':o})
  if p[2]=='messages':
   m=q('select * from messages where id=?',(p[3],),True)
   if not m:return self.sendj(404,{})
   if len(p)>4 and p[4]=='reactions':
    e=b.get('emoji'); q('insert or ignore into reactions values(?,?,?)',(m['id'],u['id'],e)); return self.sendj(200,{'reactions':msg(m)['reactions']})
   if len(p)>4 and p[4]=='pin': q('insert or ignore into pins values(?,?,?)',(m['id'],u['id'],now())); return self.sendj(200,{'pin':{'message_id':m['id'],'pinned_by':u['id']}})
  return self.sendj(404,{})
 def do_PATCH(self):
  u=self.auth()
  if not u:return self.sendj(401,{})
  b=self.body()
  if self.path=='/api/users/me':
   for k in b:
    if k not in ('display_name','timezone','avatar_url','status_text','status_emoji') or len(str(b[k]))>500:return self.sendj(400,{})
   if 'timezone' in b and b['timezone'] not in ('UTC','America/New_York','Europe/London','Asia/Tokyo'):return self.sendj(400,{})
   for k,v in b.items():q('update users set '+k+'=? where id=?',(v,u['id']))
   r=q('select * from users where id=?',(u['id'],),True); broadcast({'type':'user.updated','user':user(r)}); return self.sendj(200,{'user':user(r)})
  return self.sendj(404,{})
 def do_DELETE(self):
  u=self.auth()
  if not u:return self.sendj(401,{})
  p=self.path.split('/')
  if len(p)>4 and p[2]=='messages' and p[4]=='reactions':q('delete from reactions where message_id=? and user_id=? and emoji=?',(p[3],u['id'],urllib.parse.unquote(p[5])));return self.sendj(200,{'reactions':[]})
  if p[2]=='messages':q('update messages set deleted=1 where id=?',(p[3],));return self.sendj(200,{'deleted':True})
  return self.sendj(404,{})
 def websocket(self):
  tok=urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query).get('token',[''])[0]; r=q('select user_id from tokens where token=?',(tok,),True)
  if not r:return self.sendj(401,{})
  key=self.headers.get('Sec-WebSocket-Key'); self.send_response(101);self.send_header('Upgrade','WebSocket');self.send_header('Connection','Upgrade');self.send_header('Sec-WebSocket-Accept',base64.b64encode(hashlib.sha1((key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest()).decode());self.end_headers()
  s=self.request; ent=[s,set()];clients.append(ent)
