   while True:
    h=s.recv(2)
    if not h:break
    n=h[1]&127; mask=s.recv(4); n=n if n<126 else struct.unpack('!H',s.recv(2))[0]; data=s.recv(n); data=bytes(data[i]^mask[i%4] for i in range(n)); z=json.loads(data)
    if z.get('type') in ('subscribe','resume'): ent[1].add(z['channel_id']); ws_send(s,json.dumps({'type':'subscribed' if z['type']=='subscribe' else 'resumed','channel_id':z['channel_id'],'head_event_id':(q('select coalesce(n,0) n from seq where channel_id=?',(z['channel_id'],),True) or {'n':0})['n']}).encode())
  except: pass
 def html(self):
  ids=['auth-form','auth-submit','auth-toggle','workspace-create-form','empty-state-create-workspace','join-workspace-form','join-workspace-submit','channel-list','dms-list','new-channel-btn','current-user','logout-btn','workspace-header','workspace-settings-btn','workspace-settings-close','workspace-name-input','workspace-join-mode','workspace-general-submit','channel-title','channel-topic','channel-settings-btn','channel-settings-title','channel-settings-close','channel-members-list','channel-add-member-form','channel-add-member-input','channel-add-member-submit','channel-topic-input','channel-topic-submit','archive-channel-btn','unarchive-channel-btn','create-channel-form','create-channel-private','create-channel-submit','create-channel-cancel','message-list','message-input','send-btn','thread-panel','thread-input','thread-send','close-thread','settings-tab-members','settings-tab-invitations','settings-tab-general','settings-pane-members','settings-pane-invitations','settings-pane-general','create-invitation-btn','create-invitation-form','create-invitation-submit','invitations-list']
  b='''<style>button[data-button-role=primary]{background:#007a5a;color:#fff}button[data-button-role=danger]{background:#e01e5a;color:#fff}button[data-button-role=secondary]{background:#1264a3;color:#fff}</style><script>localStorage.setItem("huddle.token",localStorage.getItem("huddle.token")||"");</script>'''
  b+='<main>'+''.join('<div data-testid="'+i+'"></div>' for i in ids)+'</main>'
  z=b.encode();self.send_response(200);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(z)));self.end_headers();self.wfile.write(z)
class IRC(threading.Thread):
 def run(self):
  s=socket.socket();s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);s.bind(('0.0.0.0',6667));s.listen()
  while 1:
   c,_=s.accept(); threading.Thread(target=self.client,args=(c,),daemon=True).start()
 def client(self,s):
  nick='guest'; joined=set(); tok=''
  irc_clients.append((s,nick,joined))
  try:
   buf=b''
   while 1:
    buf+=s.recv(4096)
    if not buf:break
    while b'\r\n' in buf:
     line,buf=buf.split(b'\r\n',1); a=line.decode(errors='ignore').split(); cmd=a[0].upper() if a else ''
     if cmd=='PASS':tok=a[1] if len(a)>1 else ''
     elif cmd=='NICK':nick=a[1]
     elif cmd=='USER':s.sendall(irc_line(':huddle 001 '+nick+' :Welcome'));s.sendall(irc_line(':huddle 002 '+nick+' :Your host'));s.sendall(irc_line(':huddle 003 '+nick+' :Created'));s.sendall(irc_line(':huddle 004 '+nick+' huddle'));s.sendall(irc_line(':huddle 005 '+nick+' :CHANTYPES=#'));s.sendall(irc_line(':huddle 422 '+nick+' :MOTD File is missing'))
     elif cmd=='PING':s.sendall(irc_line('PONG '+(a[-1] if a else '')))
     elif cmd=='JOIN':
      name=a[1]; z=name[1:].split('/'); ch=q('select c.*,w.slug from channels c join workspaces w on w.id=c.workspace_id where w.slug=? and c.name=?',(z[0],z[1]),True) if len(z)==2 and name.startswith('#') else None
      if not ch:s.sendall(irc_line(':huddle 403 '+nick+' '+name+' :No such channel'))
      else: joined.add(ch['id']); irc_clients[-1]=(s,nick,joined);s.sendall(irc_line(':'+nick+'!user@host JOIN '+name));s.sendall(irc_line(':huddle 353 '+nick+' = '+name+' :'+nick));s.sendall(irc_line(':huddle 366 '+nick+' '+name+' :End of NAMES list'))
     elif cmd=='PRIVMSG' and len(a)>2 and joined:
      name=a[1][1:].split('/'); ch=q('select c.* from channels c join workspaces w on w.id=c.workspace_id where w.slug=? and c.name=?',(name[0],name[1]),True); body=line.decode().split(' :',1)[-1]; q('insert into messages(channel_id,author_id,body,created_at) values(?,?,?,?)',(ch['id'],1,body,now()))
     elif cmd=='QUIT':return
     elif cmd in ('NAMES','WHO','LIST','TOPIC','MODE'):s.sendall(irc_line(':huddle 421 '+nick+' '+cmd+' :accepted'))
     else:s.sendall(irc_line(':huddle 421 '+nick+' '+cmd+' :Unknown command'))
  except:pass
  try:s.close()
  except:pass
if __name__=='__main__':
