p='/app/server.py'
s=open(p).read()
a=s.index(' def client(self,s):')
b=s.index("if __name__=='__main__':",a)
new=""" def client(self,s):
  nick='guest'; joined=set(); tok=''; uid=None; registered=False
  try:
   buf=b''
   while True:
    buf+=s.recv(4096)
    if not buf: break
    while b'\\r\\n' in buf:
     line,buf=buf.split(b'\\r\\n',1)
     text=line.decode(errors='ignore'); a=text.split(); cmd=a[0].upper() if a else ''
     if cmd=='PASS':
      tok=a[1] if len(a)>1 else ''
      tr=q('select user_id from tokens where token=?',(tok,),True)
      if not tr:
       s.sendall(irc_line(':huddle 464 '+nick+' :Password incorrect'))
      else: uid=tr['user_id']
     elif cmd=='NICK':
      nn=a[1] if len(a)>1 else ''
      if any(x[1]==nn and x[0] is not s for x in irc_clients):
       s.sendall(irc_line(':huddle 433 '+nick+' '+nn+' :Nickname is already in use'))
      else:
       nick=nn
       for i,x in enumerate(irc_clients):
        if x[0] is s: irc_clients[i]=(s,nick,joined)
     elif cmd=='USER':
      if not uid:
       s.sendall(irc_line(':huddle 464 '+nick+' :Password incorrect'))
       continue
      registered=True
      for line2 in ('001 '+nick+' :Welcome','002 '+nick+' :Your host','003 '+nick+' :Created','004 '+nick+' huddle','005 '+nick+' :CHANTYPES=#','422 '+nick+' :MOTD File is missing'):
       s.sendall(irc_line(':huddle '+line2))
     elif cmd=='PING':
      s.sendall(irc_line('PONG '+(a[-1] if a else '')))
     elif cmd=='JOIN' and len(a)>1:
      name=a[1]; z=name[1:].split('/')
      ch=q('select c.*,w.slug from channels c join workspaces w on w.id=c.workspace_id where w.slug=? and c.name=?',(z[0],z[1]),True) if len(z)==2 and name.startswith('#') else None
      if not ch:s.sendall(irc_line(':huddle 403 '+nick+' '+name+' :No such channel'))
      else:
       joined.add(ch['id'])
       for i,x in enumerate(irc_clients):
        if x[0] is s: irc_clients[i]=(s,nick,joined)
       s.sendall(irc_line(':'+nick+'!user@host JOIN '+name))
       s.sendall(irc_line(':huddle 353 '+nick+' = '+name+' :'+nick))
       s.sendall(irc_line(':huddle 366 '+nick+' '+name+' :End of NAMES list'))
     elif cmd=='PRIVMSG' and len(a)>2 and joined:
      name=a[1][1:].split('/'); ch=q('select c.* from channels c join workspaces w on w.id=c.workspace_id where w.slug=? and c.name=?',(name[0],name[1]),True)
      if ch:
       body=text.split(' :',1)[-1]; ev=next_event(ch['id'])
       q('insert into messages(channel_id,author_id,body,created_at,event_id) values(?,?,?,?,?)',(ch['id'],uid,body,now(),ev))
       m=q('select * from messages where channel_id=? and author_id=? order by id desc limit 1',(ch['id'],uid),True)
       broadcast({'type':'message.created','event_id':ev,'channel_id':ch['id'],'message':msg(m)},ch['id'])
     elif cmd=='QUIT':
      return
     elif cmd in ('NAMES','WHO','LIST','TOPIC','MODE'):
      s.sendall(irc_line(':huddle 200 '+nick+' :OK'))
     elif cmd:
      s.sendall(irc_line(':huddle 421 '+nick+' '+cmd+' :Unknown command'))
  except Exception:
   pass
  finally:
   for i,x in enumerate(list(irc_clients)):
    if x[0] is s:
     try: irc_clients.remove(x)
     except ValueError: pass
   try: s.close()
   except: pass
"""
open(p,'w').write(s[:a]+new+s[b:])
