steps.message:
THOUGHT: The per-connection SQLite polling is the performance bottleneck: every subscriber serializes database access independently, causing latency and loss under concurrent writes. I’ll replace it with one process-level fan-out worker that queries each subscribed channel once per cycle and distributes each new event to all local subscribers, while each WebSocket only handles client control frames.

```mswea_bash_command
python3 - <<'PY'
p='/app/server.py'
s=open(p).read()
# replace the per-connection polling loop with a lightweight sleep
start=s.index("    for cid in list(ent[1]):", s.index(" def websocket(self):"))
end=s.index("  except: pass\n  finally:", start)
s=s[:start]+"    time.sleep(0.01)\n"+s[end:]
# add fanout worker before class H
mark="class H(BaseHTTPRequestHandler):"
worker="""def ws_fanout():
 heads={}
 while True:
  try:
   channels={}
   for c in list(clients):
    for cid in list(c[1]):
     channels.setdefault(cid,[]).append(c)
   for cid,subs in channels.items():
    head=heads.get(cid,0)
    rows=q('select * from messages where channel_id=? and event_id>? order by event_id',(cid,head))
    for m in rows:
     obj={'type':'message.reply' if m['parent_id'] else 'message.created','event_id':m['event_id'],'channel_id':cid,'message':{'id':m['id'],'channel_id':cid,'author_id':m['author_id'],'body':m['body'],'parent_id':m['parent_id'],'created_at':m['created_at']}}
     data=json.dumps(obj).encode()
     for c in list(subs):
      try:
       if c[3].get(cid,0)<m['event_id']:
        ws_send(c[0],data); c[3][cid]=m['event_id']
      except: pass
     head=max(head,m['event_id'])
    heads[cid]=head
  except: pass
  time.sleep(0.01)

"""
assert mark in s
s=s.replace(mark,worker+mark)
# start one worker per HTTP process
old="  threading.Thread(target=ws_fanout,daemon=True).start()"
if old not in s:
 s=s.replace("  if NODE == 0: threading.Thread(target=IRC().run,daemon=True).start()", "  if NODE == 0: threading.Thread(target=IRC().run,daemon=True).start()\n  threading.Thread(target=ws_fanout,daemon=True).start()")
open(p,'w').write(s)
